import re

def remove_think_tags(input_string):
    # 使用正则表达式去除 <think> 和 </think> 标签之间的内容
    result = re.sub(r'<think>.*?</think>', '', input_string, flags=re.DOTALL)
    result = result.strip()
    return result



def has_answer(output:str):
    output = remove_think_tags(output)
    return  '<answer>' in output and '</answer>' in output




